from pathlib import Path
import json
import hashlib

ROOT = Path(__file__).parent
TEMPLATE = Path('/Users/zc/.codex/skills/write-format-c-video-prompts/references/format-c-template-v2.6.md').read_text()
fixed = TEMPLATE.split('固定画质词（Fixed Quality Descriptor）：', 1)[1].split('\n\n光影基调（Lighting Tone）：', 1)[0]
fixed = '固定画质词（Fixed Quality Descriptor）：' + fixed
S = 'Silas日常穿搭.png'
M = 'Madison日常穿搭_北桥校徽修正版.png'
E = 'Elena.png'

def write_group(stem, group, dur, quality, light, beat, cycle, flow, lock, shot, audio_text, actors):
    body = f'【组头｜{group}｜固定画质词与光影基调】\n{fixed}\n\n光影基调（Lighting Tone）：{light}\n节奏结构（Beat Structure）：组型：第五集开头事实清算的独立闪回补镜｜1镜｜共{dur:.1f}s；{beat} 英文旁白及动作时间均为未实测估算，实际音频若超时须加长，不删词、不重复计时。\n景别循环（Shot Size Cycle）：{cycle}\n视觉动线（Visual Flow）：{flow}\n引用锁/项目参数：九梦2.5 Pro／480P，9:16；本组按用户指定单镜闪回制作，不凑多镜；摄影覆盖项：本shot明确焦段覆盖固定画质段默认85mm，镜头保持真人自然透视。{lock} 角色图只继承允许的身份、五官、发型、体型与本镜指定服装，不继承图板、文字、装饰边框、分屏拼贴及无关配件。场景为本次附件的文字设计，没有对应已核对原生场景卡，不引用其他场景图冒充。所有背景只保留空场及静态陈设，无群演、无经过门口或玻璃后的人影、无镜面重复人。\n\n{shot}\n'
    dest = ROOT / f'{stem}.txt'
    dest.write_text(body)
    bindings = []
    for asset, anchor in actors:
        bindings.append(dict(section='header', anchor=f'角色身份锁{asset}', asset=asset, category='角色'))
        bindings.append(dict(section='shot1', anchor=anchor, asset=asset, category='角色'))
    bindings.append(dict(section='shot1_audio', anchor=audio_text, asset='【音色】Elena.png', category='角色'))
    (ROOT / f'{stem}_bindings.json').write_text(json.dumps(bindings, ensure_ascii=False, indent=2))
    assert len(body) < 4900, len(body)
    assert body.count(fixed) == 1
    for b in bindings:
        assert body.count(b['anchor']) == 1, (stem, b['anchor'], body.count(b['anchor']))
    return dict(file=dest.name, chars=len(body), sha256=hashlib.sha256(body.encode()).hexdigest(), duration=dur, bindingCount=len(bindings), audio=audio_text, quality=quality)

